import React from 'react';
import { ChevronLeft, ChevronRight, ChevronDoubleLeft, ChevronDoubleRight } from '@hexa-ui/icons';
import Styled from './Pages.styles';
import PageSlot from '../PageSlot/PageSlot';
import { usePagination } from '../../hooks/usePagination';
import { onKeyEnter } from '../../utils/utils';

const Pages = ({
  disabled = false,
  currentPage,
  handlePageChange,
  pageSize,
  total,
}: {
  total: number;
  disabled: boolean | undefined;
  currentPage: number;
  handlePageChange: (pageNumber: number) => void;
  pageSize: number;
}): JSX.Element => {
  const pages = usePagination({ totalCount: total, currentPage, pageSize });
  return (
    <Styled.Container>
      <Styled.List>
        <Styled.NavigatorContainer
          onClick={() => handlePageChange(1)}
          onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
            onKeyEnter(e, () => handlePageChange(1))
          }
          isDoubleLeft
          disabled={disabled || currentPage === 1}
          tabIndex={disabled || currentPage === 1 ? -1 : 0}
          title="first page"
        >
          <Styled.Anchor
            aria-label="go to page 1"
            rel="nofollow"
            aria-disabled={disabled || currentPage === 1 ? true : undefined}
          >
            <ChevronDoubleLeft size="medium" />
          </Styled.Anchor>
        </Styled.NavigatorContainer>
        <Styled.NavigatorContainer
          bordered
          onClick={() => handlePageChange(currentPage - 1)}
          onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
            onKeyEnter(e, () => handlePageChange(currentPage - 1))
          }
          disabled={disabled || currentPage === 1}
          tabIndex={disabled || currentPage === 1 ? -1 : 0}
          title="previous page"
        >
          <Styled.Anchor
            aria-label="go to previous page"
            rel="nofollow"
            aria-disabled={disabled || currentPage === 1 ? true : undefined}
          >
            <ChevronLeft size="medium" />
          </Styled.Anchor>
        </Styled.NavigatorContainer>
        {pages.map((slot) => (
          <PageSlot
            handlePageChange={handlePageChange}
            label={slot.toString()}
            key={slot}
            disabled={disabled}
            isSelected={currentPage === slot}
          />
        ))}
        <Styled.NavigatorContainer
          bordered
          onClick={() => handlePageChange(currentPage + 1)}
          onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
            onKeyEnter(e, () => handlePageChange(currentPage + 1))
          }
          disabled={disabled || currentPage === Math.ceil(total / pageSize)}
          tabIndex={disabled || currentPage === Math.ceil(total / pageSize) ? -1 : 0}
          title="next page"
        >
          <Styled.Anchor
            aria-label="go to next page"
            rel="nofollow"
            aria-disabled={
              disabled || currentPage === Math.ceil(total / pageSize) ? true : undefined
            }
          >
            <ChevronRight size="medium" />
          </Styled.Anchor>
        </Styled.NavigatorContainer>
        <Styled.NavigatorContainer
          onClick={() => handlePageChange(Math.ceil(total / pageSize))}
          onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
            onKeyEnter(e, () => handlePageChange(Math.ceil(total / pageSize)))
          }
          isDoubleRight
          disabled={disabled || currentPage === Math.ceil(total / pageSize)}
          tabIndex={disabled || currentPage === Math.ceil(total / pageSize) ? -1 : 0}
          title="last page"
        >
          <Styled.Anchor
            aria-label="go to last page"
            rel="nofollow"
            aria-disabled={
              disabled || currentPage === Math.ceil(total / pageSize) ? true : undefined
            }
          >
            <ChevronDoubleRight size="medium" />
          </Styled.Anchor>
        </Styled.NavigatorContainer>
      </Styled.List>
    </Styled.Container>
  );
};

export default Pages;
